      "marker": "Questions 159 and 160 are based on the following information.",
      "context": "The following table shows the time needed to cook a turkey based on the\n weight of the turkey and the temperature of the oven. After the turkey is\n removed from the oven, it should be left to rest for 30 minutes before it’s\n carved to ensure that it remains juicy.\n\n  Weight of Turkey (Pounds) Cooking Time at 325°F Cooking Time at 375°F\n\n 8–12 lb.                     2.5–3.0 hours       2.0–2.5 hours\n 12–16 lb.                    3.0–3.5 hours       2.5–3.0 hours\n 16–20 lb.                    3.5–4.0 hours       3.0–3.5 hours\n 20–24 lb.                    4.0–4.5 hours       3.5–4.0 hours",
