          "text": "701. According to the table and the given information, which of the\n   following is a true statement?\n   (A) A day on Venus takes longer than a year on Venus.\n   (B) All planets have at least one moon.\n   (C) All planets take approximately one Earth year to orbit the sun.\n   (D) The sum of the masses of all of the planets is greater than the\n     mass of the sun.\n\nUse the following information for",
