          "text": "702. According to the figure and the given information, which of the\n     following is a true statement?\n     (A) Cancer is now the leading cause of death.\n     (B) The number of deaths due to heart disease has more than\n       doubled since 1950.\n     (C) Although heart disease is still the leading cause of death, the\n       number of deaths due to cancer has increased steadily since 1950.\n     (D) The number of deaths via cancer was approximately the same in\n       2014 as it was in 1960.",
