          "text": "740. Based on the excerpt, cooking allows you to control all of the\n    following EXCEPT\n    (A) how much a meal at your favorite restaurant costs.\n    (B) the ingredients that go into the meal.\n    (C) the flavors of the food.\n    (D) the health profile of the food.",
          "sourcePage": 303
