          "number": 800,
          "text": "800. Select the best sentence from among the given choices.\n   (A) As you develop the essential idea behind the new direction,\n     compare them to the idea that launched your business in the first\n     place.\n   (B) Developing the essential idea behind the new direction, compare\n     it to the idea that launched your business in the first place.\n   (C) Having developed the essential idea behind the new direction\n     compare it to the idea that launched your business in the first\n     place.\n   (D) As you develop the essential idea behind the new direction,\n     compare it to the idea that launched your business in the first\n     place.",
