          "number": 827,
          "text": "827. According to the passage, why are TV shows about forensic\n    science so popular?\n    (A) People have a macabre fascination with death.\n    (B) People take guilty pleasure in watching criminals in action.\n    (C) People are curious about nature and seek scientific knowledge.\n    (D) The passage does not specify.",
