          "text": "834. How did increased access to modern transportation reduce the\n   effectiveness of the old crime-solving methods?\n   (A) It meant that criminals could escape from the crime scene faster\n     than before.\n   (B) It had no effect.\n   (C) It made eyewitness accounts less reliable.\n   (D) It made confessions less reliable.",
          "sourcePage": 347
