      "marker": "Questions 852 through 858 are based on the following passage. The",
      "context": "passage is not complete. You have to select the best sentence or\ncompletion of a sentence from among the given choices.\n\n This excerpt is from Staying Sharp For Dummies by the American\n Geriatrics Society and the Health in Aging Foundation (Wiley).\n SEE QUESTION 852 The exciting thing is that science now provides\n evidence for what works and what doesn’t. Training your brain no longer\n has to be a case of trial and error.\n SEE QUESTION 853 With 100 billion cells, your brain is like the CEO\n of a giant corporation. How can something so small have so much\n responsibility? SEE QUESTION 854\n Brain training is a growing area of interest, both in research and in the\n public mind. Exciting emerging evidence indicates that you can train\n your brain and, as a result, change your circumstances. But what works\n and what doesn’t? Can everyone benefit from brain training?\n SEE QUESTION 855 Although you may have heard that you’re stuck\n with the brain you have, scientific research has now found that this isn’t\n true!\n You’re probably familiar with the left brain and the right brain. Well, it’s\n true that the brain is made up of left and right hemispheres, which do\n have different functions. However, the idea that some people are only\n left-brainers and others are only right-brainers isn’t entirely true. For\n example, language skills are located in the left hemisphere and everyone\n uses this part of the brain! You don’t need to hide behind the excuse that\n\nyou’re a right-brainer so you can’t do math calculations. With the\nactivities included in this book, you can get both halves of your brain\nworking at their optimum levels.\nSEE QUESTION 856 When you train one part of the brain, the whole\nbrain benefits. You can think of the brain like an orchestra or a sports\nteam. The message is the same — one star player can’t carry the rest of\nthe team.\nMental health refers to your state of being. Are you happy? When do\nyou find yourself frustrated? Do you feel stressed out? What makes you\nfeel anxious? These questions are important in determining how well\nyour brain functions, so make sure you pay attention to your mental\nhealth. SEE QUESTION 857\nDon’t take your passions and hobbies for granted. Discover how they\ncan make your brain more creative. A more creative brain is a smarter\nbrain. SEE QUESTION 858\nGetting swept into myriad things that demand your attention on a daily\nbasis is easy. Yet, in this ever-demanding environment, finding time to\nquiet your brain and create a space for contemplation is increasingly\nimportant”",
