          "text": "866. Why does the author appear to misspell the words spoken by the\n   boy when he says phrases like “It’s a-movin’” and “I’m a-goin’\n   ’ome, I am”?\n   (A) The story was written before automated spell-checkers were\n     invented.\n   (B) The author is a terrible writer and doesn’t understand the rules of\n     spelling or grammar.\n   (C) The author wanted to display the boy’s character to the reader by\n     spelling the words in the manner in which the boy says them.\n   (D) The rules of spelling and grammar were very different when the\n     story was written.",
