      "id": "group-874-880",
      "section": "Science",
      "questionStart": 874,
      "questionEnd": 880,
      "rangeLabel": "Questions 874–880",
      "contextType": "passage",
      "marker": "Questions 874 through 880 are based on the following passage. The",
      "context": "passage is not complete. You have to select the best sentence or\ncompletion of a sentence from among the given choices.\n\nThe following excerpt is from Business Writing For Dummies by Natalie\nCanavor (Wiley).\nIn both your personal and professional lives, you may occasionally find\ncause to write complaints. When that happens, you get much better\nresults if you do it well. A written complaint offers a great demonstration\nof how to use the planning process.\nSEE QUESTION 874 You may not have achieved what you wanted or\nmay feel disappointed, but written complaints last a long time —\nforever, more or less. People take written complaints and criticism very\nseriously. So never draft and send such a message in the heat of the\nmoment. Step-by-step planning helps you remove yourself from the\nemotional context and attendant risks.\nSEE QUESTION 875 For example, you might say, ‘Hi Jack, how’s it\ngoing? We noticed there’s a long delay till our calls for service get\nhandled. What’s up?’ This is a good, neutral way to start the interaction.\nIf making a call or having a conversation doesn’t seem to help, plan a\nletter. Suppose a supplier has disappointed you with the quality of goods\nor services delivered. Perhaps computer maintenance work has been\npoorly performed. Articulating your goal is critical.\nSEE QUESTION 876 Writing from anger is a self-indulgent approach\nthat frequently boomerangs. You may not know an important part of the\nstory, so proceed very cautiously before burning bridges. In any case, the\nworld is small, and a person you attack may have friends you could\nencounter in the future.\nYour goal may better be stated as one or more of the following:\n\n   Resolve a dispute\n   Solve a problem\n   Gain a concession\n   Get a refund\n   Get an apology or acknowledgment\n\nSEE QUESTION 877 Putting your reader on the defensive is never to\nyour advantage. Stick to the facts, not how you feel. Adopt a tone that\nconveys an assumption that the problem can be fixed. As the saying\nsays, no point biting off your nose to spite your face. Is the disappointing\nsupplier the only one who has what you need? Will finding a new source\nthreaten your production deadlines or up the costs? Review the\nramifications to help you feel more objective. Resolve to give the other\nparty a chance to perform.\nFor example, you can complain about a computer maintenance issue:\nDear Bob,\nSEE QUESTION 878 During the first quarter of this year, we made 16\ncalls to your office and in 12 cases, response took two to three days. As\nyou know, the network’s critical to all our operations and such delays\nare expensive for us.\nSEE QUESTION 879.\nPlease look into this and get back to me at your earliest convenience. I’d\nlike to know why the problem is happening and what steps you can take\nto deliver the service we need.\nThank you for your immediate attention. I hope these issues can be\nquickly resolved.\nBest, Elaine\nThe tone and language are low-key and neutral, and Bob will notice that\nElaine sees the problem as fixable. But he’ll have no trouble recognizing\nthat the contract is at risk. SEE QUESTION 880",
