          "text": "895. According to the passage, which of the following is a true\n     statement?\n     (A) A 3D printer stores an object in a cupboard, translating it into a\n       series of very thick slices, and then builds the object two layers a\n       time.\n     (B) A 3D printer stores an object in a computer, translating it into a\n       series of very thin slices, and then builds the object one layer at a\n       time.\n     (C) A 3D printer stores an object in a computer, translating it into a\n       series of very thick slices, and then builds the object several layers\n       at a time.\n     (D) A 3D printer stores an object in a computer, translating it into a\n       series of very thin slices, and then builds the object five layers at a\n       time.",
