      "rangeLabel": "Questions 897–904",
      "contextType": "passage",
      "marker": "Questions 897 through 904 are based on the following passage.",
      "context": "The following excerpt is from Wine For Dummies by Ed McCarthy and\n Mary Ewing-Mulligan (Wiley).\n We know plenty of people who enjoy drinking wine but don’t know\n much about it. (Been there, done that ourselves.) Knowing a lot of\n information about wine definitely isn’t a prerequisite to enjoying it. But\n\nfamiliarity with certain aspects of wine can make choosing wines a lot\neasier, enhance your enjoyment of wine, and increase your comfort\nlevel. You can master as much or as little as you like. The journey begins\nhere.\nIn its most basic form, winemaking is that simple. After the grapes are\ncrushed, yeasts (tiny one-celled organisms that exist naturally in the\nvineyard and, therefore, on the grapes) come into contact with the sugar\nin the grapes’ juice and gradually convert that sugar into alcohol. Yeasts\nalso produce carbon dioxide, which evaporates into the air. When the\nyeasts are done working, your grape juice is wine. The sugar that was in\nthe juice is no longer there — alcohol is present instead. (The riper and\nsweeter the grapes, the more alcohol the wine will have.) This process is\ncalled fermentation.\nFermentation is a totally natural process that doesn’t require man’s\nparticipation at all, except to put the grapes into a container and release\nthe juice from the grapes. Fermentation occurs in fresh apple cider left\ntoo long in your refrigerator, without any help from you. We read that\neven milk, which contains a different sort of sugar than grapes do,\ndevelops a small amount of alcohol if left on the kitchen table all day\nlong.\nSpeaking of milk, Louis Pasteur is the man credited with discovering\nfermentation in the 19th century. That’s discovering, not inventing.\nSome of those apples in the Garden of Eden probably fermented long\nbefore Pasteur came along. (Well, we don’t think it could have been\nmuch of an Eden without wine!)\nNow if every winemaker actually made wine in as crude a manner as we\njust described, we’d be drinking some pretty rough stuff that would\nhardly inspire us to write a book about wine. But today’s winemakers\nhave a bag of tricks as big as a sumo wrestler’s appetite, which is one\nreason no two wines ever taste exactly the same.\nThe men and women who make wine can control the type of container\nthey use for the fermentation process (stainless steel and oak are the two\nmain materials) as well as the size of the container and the temperature\n\nof the juice during fermentation — and every one of these choices can\nmake a real difference in the taste of the wine.\nAfter fermentation, winemakers can choose how long to let the wine\nmature (a stage when the wine sort of gets its act together) and in what\nkind of container. Fermentation can last three days or three months, and\nthe wine can then mature for a couple of weeks or a couple of years or\nanything in between. (If you have trouble making decisions, don’t ever\nbecome a winemaker.)\nObviously, one of the biggest factors in making one wine different from\nthe next is the nature of the raw material, the grape juice. Besides the\nfact that riper, sweeter grapes make a more alcoholic wine, different\nvarieties of grapes (Chardonnay, Cabernet Sauvignon, or Merlot, for\nexample) make different wines. Grapes are the main ingredient in wine,\nand everything the winemaker does, he does to the particular grape juice\nhe has.",
