          "text": "901. Why do the authors say, “Well, we don’t think it could have been\n   much of an Eden without wine!”?\n   (A) They know that wine was invented in Eden.\n   (B) Eden is famous for its wide variety of wine.\n   (C) The best gardens for growing grapes are found just east of Eden.\n   (D) They’re attempting to be humorous.",
