          "text": "902. According to the passage, after all the ingredients have been\n   collected and prepared, winemakers can still control the taste of the\n   wine produced during the fermentation process by selecting all of\n   the following factors EXCEPT\n   (A) the material used for the brewing container.\n   (B) the temperature of the juice.\n   (C) the type of grapes used.\n   (D) the size of the brewing container.",
