          "number": 907,
          "text": "907. If you are having trouble understanding someone’s signs, which of\n   the following actions would be unacceptable?\n   (A) asking the person to repeat what he or she just said\n   (B) stopping the person and letting him or her know where you\n     stopped understanding\n   (C) slapping your forehead and shouting, “Speak up, fool!”\n   (D) considering the context of the conversation and imagining what\n     the other person could have meant",
