      "rangeLabel": "Questions 913–920",
      "contextType": "information",
      "marker": "Questions 913 through 920 are based on the following two poems by",
      "context": "WWI veteran Siegfried Sassoon.\n\n Survivors\n\nNo doubt they'll soon get well; the shock and strain\nHave caused their stammering, disconnected talk.\nOf course they're ‘longing to go out again,' —\nThese boys with old, scared faces, learning to walk.\nThey'll soon forget their haunted nights; their cowed\nSubjection to the ghosts of friends who died,—\nTheir dreams that drip with murder; and they'll be proud\nOf glorious war that shatter'd all their pride…\nMen who went out to battle, grim and glad;\nChildren, with eyes that hate you, broken and mad.\nCraiglockart Hospital. October, 1917. Siegfried Sassoon\nSuicide in the Trenches\nI knew a simple soldier boy\nWho grinned at life in empty joy,\nSlept soundly through the lonesome dark,\nAnd whistled early with the lark.\nIn winter trenches, cowed and glum,\nWith crumps and lice and lack of rum,\nHe put a bullet through his brain.\nNo one spoke of him again.\nYou smug-faced crowds with kindling eye\nWho cheer when soldier lads march by,\nSneak home and pray you'll never know\nThe hell where youth and laughter go.",
