      "contextType": "passage",
      "marker": "Questions 938 through 945 are based on the following passage.",
      "context": "The following excerpt is from The Secret Life of Dust by Hannah\n Holmes (Wiley).\n Flying diatoms don’t add significantly to the airborne vegetable matter,\n in terms of simple tonnage. But when these glass-shelled algae do take a\n spin through the atmosphere, they raise interesting questions. They seem\n to defy the size limit for far-flying dust, for one thing. And they may\n sometimes fly with a purpose.\n Michael Ram, a professor of physics at the University of Buffalo, has\n become an expert at teasing these tiny organisms out of ice cores from\n Antarctica and Greenland. Deep glaciers preserve thousands upon\n thousands of fine layers, each representing a year. And trapped in each\n layer is a sprinkling of fallen desert dust, Stardust, volcanic ash, pollen,\n insect parts — and diatoms. Ram melts a bit of ice, then puts the\n remaining sediment under a microscope.\n The diatoms, he says, stand out due to their geometric perfection. Desert\n dust, under the microscope, resembles shattered rock. But diatoms often\n resemble delicately etched pill-boxes or broken shards of the same.\n Most diatoms spend their brief lives adrift in rivers, ponds, lakes, and\n oceans. And when they die, their little shells sink. Ram says the ideal\n source of diatom dust is a shallow lake that shrinks in the dry season,\n\nexposing the sediment at its edges to the wind. Africa and the western\nUnited States are both pocked with excellent candidates.\nRam originally intended to use the diatoms he found to trace the source\nof the dust and diatoms in each sample: if the ice of one century was rich\nin North American diatoms, and the next century's ice held African\ndiatoms, he could conclude that the prevailing wind had shifted. This\nmight reveal something about the dynamics of climate change. But\nRam's diatoms proved coy about their place of origin. Many of them\nlook alike. Scientists with more diatom expertise are pursuing this line of\ninquiry.\nAnd Ram’s diatoms have caused additional head scratching. Generally,\nscientists don’t expect things much larger than a few hundredths of a\nhair's width to fly long distances. But Ram has seen disks as wide as a\nhundred, or even two hundred, microns — that’s a whopping two hairs\nin diameter. “These diatoms are large, but they have a large surface area,\nand they’re light,” Ram speculates in the accent that remains from his\nEuropean upbringing. “They’re like Frisbees. They’re very\naerodynamic.”\nThe size of the diatoms may also relate to the strength of the wind that\nlifted them. An uncommonly strong wind can lift uncommonly large\ndust, as a survey of hailstone cores has suggested. Carried up into a\nstorm cloud and then coated in ice until they fell again have been such\n“dusts” as small insects, birds, and at least one gopher tortoise. Perhaps a\nlarge diatom is not such a challenge.\nBut a third source of puzzlement is what appears to be a complete\ncolony of diatoms that evidently dwelled smack atop the Greenland\nglacier about four hundred years ago. It is common for living diatoms to\nblow into melt pools at the edges of glaciers and there start a family. But\nthe founder of the little clan Ram discovered apparently flew all the way\nto the center of the immense island before dropping into a puddle. And\nthat pioneer was still in good enough shape to launch a modest dynasty.",
