      "marker": "Questions 946 through 955 are based on the following passage. The",
      "context": "passage is not complete. You have to select the best sentence or\ncompletion of a sentence from among the given choices.\n\n The following excerpt is from YouTube Channels For Dummies by Rob\n Ciampa and Theresa Moore (Wiley).\n Anyone that wants to show off their video prowess or share their vision\n with the world can hang a virtual shingle on YouTube by starting their\n own channel. SEE QUESTION 946 These days, you can multiply those\n stubby digits by 100 million to count the number of YouTube channels.\n SEE QUESTION 947\n\nHaving more than 500 million channels can make getting noticed on\nyour channel feel like searching for a virtual needle in an online\nhaystack. SEE QUESTION 948 But it’s not all bad news — you also\nhave an advantage over your counterpart in the 1940s. SEE QUESTION\n949 Today? Not so much. In fact, if you just want a platform for\npresenting some of your video work, YouTube can make that possible\nwithout you having to fork over one thin dime.\nKnowing that YouTube is free should reduce some of your worries — at\nleast from a financial perspective. Couple that with the size and diversity\nof the YouTube audience — and the endless number of topics that\ninterest them — it’s easy to believe that you have a fair chance of\nsuccess for your channel. That’s true, up to a point — the point being\nthat, if you want your channel to thrive, you need to provide your\nviewers with compelling content.\nSEE QUESTION 950 But content merely makes up the first part of the\nequation; the rest depends on how you bring viewers to that content —\nYouTube is free, video production certainly is not. Unless you want to\nshell out money from your own pocket, you need to generate some funds\nto produce content for your channel. In the world of YouTube, one major\nway to generate such funds is through advertising revenue — SEE\nQUESTION 951 How much depends on your needs and ambitions, but\nincreased revenue can lead to better production values, which brings it\nall back to more revenue.\nSEE QUESTION 952\nLike snowflakes on a winter day, or episodes of Law and Order, there\nare more topics that viewers can appreciate on YouTube than any human\ncan count. SEE QUESTION 953\nOn the downside, you’re not the only one hoping to get noticed on\nYouTube. Many others with the very same intention are looking to build\nan audience for their YouTube channels, too. (SEE QUESTION 954\nThe number exceeds the number of those pre-approved credit card\napplications that plague your mailbox, so we’re talking lots.)\n\nYour journey on YouTube begins with knowing your strengths. Some\nusers relish documenting the quirks of their existence to the gentle\namusement of others. Others have some type of expertise to share. SEE\nQUESTION 955 — the list could go on and on. Even businesses realize\nit’s a great place to inform consumers about their products or provide a\ngreat level of customer service. Regardless of your passion, a potential\naudience is waiting for you.",
