      "marker": "Questions 956 through 964 are based on the following passage. The",
      "context": "passage is not complete. You have to select the best sentence or\ncompletion of a sentence from among the given choices.\n\n The following excerpt is from Twitter For Dummies by Laura Fitton\n (Wiley).\n You may have heard of Twitter but have no idea what it actually is. SEE\n QUESTION 956 — whether you know them personally or not. It also\n\nlets you share what you’re doing with the world — everyone from your\nfamily and friends to complete strangers. (SEE QUESTION 957) MIT\nProfessor Andrew McAfee (@amcafee) describes Twitter this way:\n“With Twitter, my friends are never far away.”\nMcAfee was most certainly right, because Twitter’s company data in\nJuly 2014 showed that 115 million active monthly users were sending\nmore than 53 million Tweets daily. SEE QUESTION 958 Additionally,\nof those 53 million Tweets, almost 40 percent were sent from mobile\ndevices such as cellphones and tablets.\nSEE QUESTION 959 It’s a social network — a digital abstraction that\ninterested in (whether you know them personally or not) — that you can\naccess from your computer or your mobile device anywhere that has an\nInternet connection.\nSEE QUESTION 960, through the Twitter website (https:// twitter.com),\nthrough the Twitter application on a mobile device, or by way of the\nnumerous third-party applications that are available for both.\nThink you can’t say anything meaningful in 140 characters? Think\nagain. Twitterers (people who use Twitter) are not only innovating clever\nforms of one-liners, haiku, quotes, stories, and humor, but also including\nimages and links to things like websites and blog posts, which carry a lot\nmore information and context. Writing 140-character messages seems\ntrivial. SEE QUESTION 961 Consider: “Man Lands on Moon.”\nSEE QUESTION 962 When you think about how millions of people\naround the world are posting Twitter messages, following other people’s\nTwitter streams, and responding to one another, you can start to see the\nsignificance behind Twitter’s appeal. In fact, Twitter has noticed that it\nacts like a “pulse of the planet,” a record of what everyone is thinking\nabout, talking about, doing, and feeling — right now. Now, that’s pretty\ninteresting!\nTrue, Twitter can look like it’s full of noise. But once you find\ninteresting people and accounts to follow, your Twitter stream shifts\nfrom a cascade of disjointed chatter to one of the most versatile, useful\n\nonline communications tools yet seen — that is, if you take the time to\nfind out how to use that tool correctly.\nTwitter is a great way for you or your company to connect with large\nnumbers of people quickly and personally, just as though you were\nhaving a conversation. SEE QUESTION 963 Or, if you prefer a work\nmetaphor, Twitter is like the office water cooler, where any number of\ninformal (or formal) conversations can take place.\nSEE QUESTION 964 The web offers a lot of information. Twitter can\nturn those long articles, lengthy conversations, and far-reaching\nconnections into easily digestible facts, thoughts, questions, ideas,\nconcepts, and sound bites. In other words, when you have only 140\ncharacters, you have to be succinct.",
