          "text": "956. Select the best completion of the sentence from among the given\n    choices.\n    (A) Twitter is basic a powerful social network that allows you to\n      keep up with the people, businesses, and organizations you’re\n      interested in\n    (B) Twitter is basically a powerful social network that allows you to\n      keep up with the people, businesses, and organizations you’re\n      interested in\n    (C) Twitter is basic a powerful social network that allows one to\n      keep up with the people, businesses, and organizations you’re\n      interested in\n    (D) Twitter is basically a powerful social network that allows one to\n      keep up with the people, businesses, and organizations you’re\n      interested in",
