          "text": "960. Select the best completion of a sentence from among the given\n   choices.\n   (A) Twitter has one central feature, it lets users instantly post entries\n     of 140 characters or less, known as Tweets\n   (B) Twitter has one central feature: It lets users instantly post entries\n     of 140 characters or less, known as Tweets\n   (C) Twitter has one central feature, it let users instantly post entries\n     of 140 characters or less, known as Tweets\n\n   (D) Twitter has one central feature: It let’s users instantly post\n     entries of 140 characters or less, known as Tweets",
