      "id": "group-965-972",
      "section": "Science",
      "questionStart": 965,
      "questionEnd": 972,
      "rangeLabel": "Questions 965–972",
      "contextType": "passage",
      "marker": "Questions 965 through 972 are based on the following passage.",
      "context": "This excerpt is from “Rip Van Winkle” by Washington Irving.\n Whoever has made a voyage up the Hudson must remember the Catskill\n Mountains. They are a branch of the great Appalachian family, and are\n seen away to the west of the river, swelling up to a noble height, and\n lording it over the surrounding country. Every change of season, every\n change of weather, indeed, every hour of the day, produces some change\n in the magical hues and shapes of these mountains, and they are\n regarded by all the goodwives, far and near, as perfect barometers.\n At the foot of these fairy mountains the traveler may have seen the light\n smoke curling up from a village, whose shingle roofs gleam among the\n trees, just where the blue tints of the upland melt away into the fresh\n green of the nearer landscape. It is a little village of great age, having\n been founded by some of the Dutch colonists in the early times of the\n province, just about the beginning of the government of the good Peter\n\nStuyvesant (may he rest in peace!), and there were some of the houses of\nthe original settlers standing within a few years, built of small yellow\nbricks brought from Holland, having latticed windows and gable fronts,\nsurmounted with weathercocks.\nIn that same village, and in one of these very houses, there lived, many\nyears since, while the country was yet a province of Great Britain, a\nsimple, good-natured fellow, of the name of Rip Van Winkle. He was a\ndescendant of the Van Winkles who figured so gallantly in the chivalrous\ndays of Peter Stuyvesant, and accompanied him to the siege of Fort\nChristina. He inherited, however, but little of the martial character of his\nancestors. I have observed that he was a simple, good-natured man; he\nwas, moreover, a kind neighbor and an obedient, henpecked husband.\nCertain it is that he was a great favorite among all the goodwives of the\nvillage, who took his part in all family squabbles; and never failed,\nwhenever they talked those matters over in their evening gossipings, to\nlay all the blame on Dame Van Winkle. The children of the village, too,\nwould shout with joy whenever he approached. He assisted at their\nsports, made their playthings, taught them to fly kites and shoot marbles,\nand told them long stories of ghosts, witches, and Indians. Whenever he\nwent dodging about the village, he was surrounded by a troop of them,\nhanging on his skirts, clambering on his back, and playing a thousand\ntricks on him; and not a dog would bark at him throughout the\nneighborhood.\nThe great error in Rip’s composition was a strong dislike of all kinds of\nprofitable labor. It could not be from the want of perseverance; for he\nwould sit on a wet rock, with a rod as long and heavy as a lance, and fish\nall day without a murmur, even though he should not be encouraged by a\nsingle nibble. He would carry a fowling piece on his shoulder for hours\ntogether, trudging through woods and swamps, and up hill and down\ndale, to shoot a few squirrels or wild pigeons. He would never refuse to\nassist a neighbor even in the roughest toil, and was a foremost man at all\ncountry frolics for husking Indian corn, or building stone fences; the\nwomen of the village, too, used to employ him to run their errands, and\nto do such little odd jobs as their less obliging husbands would not do for\n\nthem. In a word, Rip was ready to attend to anybody’s business but his\nown; but as to doing family duty, and keeping his farm in order, he found\nit impossible.\nHis children, too, were as ragged and wild as if they belonged to nobody.\nHis son Rip promised to inherit the habits, with the old clothes, of his\nfather. He was generally seen trooping like a colt at his mother’s heels,\nequipped in a pair of his father’s cast-off breeches, which he had much\nado to hold up with one hand, as a fine lady does her train in bad\nweather.\nRip Van Winkle, however, was one of those happy mortals, of foolish,\nwell-oiled dispositions, who take the world easy, eat white bread or\nbrown, whichever can be got with least thought or trouble, and would\nrather starve on a penny than work for a pound. If left to himself, he\nwould have whistled life away in perfect contentment; but his wife kept\ncontinually dinning in his ear about his idleness, his carelessness, and\nthe ruin he was bringing on his family. Morning, noon, and night, her\ntongue was incessantly going, and everything he said or did was sure to\nproduce a torrent of household eloquence. Rip had but one way of\nreplying to all lectures of the kind, and that, by frequent use, had grown\ninto a habit. He shrugged his shoulders, shook his head, cast up his eyes,\nbut said nothing. This, however, always provoked a fresh volley from his\nwife; so that he was fain to draw off his forces, and take to the outside of\nthe house — the only side which, in truth, belongs to a henpecked\nhusband.",
