      "contextType": "passage",
      "marker": "Questions 973 through 980 are based on the following passage.",
      "context": "This excerpt is from The Strange Case of Dr. Jekyll and Mr. Hyde by\n Robert Louis Stevenson.\n Nearly a year later, in the month of October, 18—, London was startled\n by a crime of singular ferocity and rendered all the more notable by the\n high position of the victim. The details were few and startling. A maid\n servant living alone in a house not far from the river, had gone up-stairs\n to bed about eleven. Although a fog rolled over the city in the small\n hours, the early part of the night was cloudless, and the lane, which the\n maid’s window overlooked, was brilliantly lit by the full moon. It seems\n she was romantically given, for she sat down upon her box, which stood\n immediately under the window, and fell into a dream of musing. Never\n\n(she used to say, with streaming tears, when she narrated that\nexperience), never had she felt more at peace with all men or thought\nmore kindly of the world. And as she so sat she became aware of an\naged and beautiful gentleman with white hair, drawing near along the\nlane; and advancing to meet him, another and very small gentleman, to\nwhom at first she paid less attention. When they had come within speech\n(which was just under the maid’s eyes) the older man bowed and\naccosted the other with a very pretty manner of politeness.\nIt did not seem as if the subject of his address were of great importance;\nindeed, from his pointing, it sometimes appeared as if he were only\ninquiring his way; but the moon shone on his face as he spoke, and the\ngirl was pleased to watch it, it seemed to breathe such an innocent and\nold-world kindness of disposition, yet with something high too, as of a\nwell-founded self-content. Presently her eye wandered to the other, and\nshe was surprised to recognise in him a certain Mr. Hyde, who had once\nvisited her master and for whom she had conceived a dislike. He had in\nhis hand a heavy cane, with which he was trifling; but he answered never\na word, and seemed to listen with an ill-contained impatience. And then\nall of a sudden he broke out in a great flame of anger, stamping with his\nfoot, brandishing the cane, and carrying on (as the maid described it) like\na madman. The old gentleman took a step back, with the air of one very\nmuch surprised and a trifle hurt; and at that Mr. Hyde broke out of all\nbounds and clubbed him to the earth. And next moment, with ape-like\nfury, he was trampling his victim under foot and hailing down a storm of\nblows, under which the bones were audibly shattered and the body\njumped upon the roadway. At the horror of these sights and sounds, the\nmaid fainted.\nIt was two o’clock when she came to herself and called for the police.\nThe murderer was gone long ago; but there lay his victim in the middle\nof the lane, incredibly mangled. The stick with which the deed had been\ndone, although it was of some rare and very tough and heavy wood, had\nbroken in the middle under the stress of this insensate cruelty; and one\nsplintered half had rolled in the neighbouring gutter — the other, without\ndoubt, had been carried away by the murderer. A purse and a gold watch\nwere found upon the victim: but no cards or papers, except a sealed and\n\nstamped envelope, which he had been probably carrying to the post, and\nwhich bore the name and address of Mr. Utterson.\nThis was brought to the lawyer the next morning, before he was out of\nbed; and he had no sooner seen it, and been told the circumstances, than\nhe shot out a solemn lip. “I shall say nothing till I have seen the body,”\nsaid he; “this may be very serious. Have the kindness to wait while I\ndress.” And with the same grave countenance he hurried through his\nbreakfast and drove to the police station, whither the body had been\ncarried. As soon as he came into the cell, he nodded.\n“Yes,” said he, “I recognise him. I am sorry to say that this is Sir\nDanvers Carew.”\n“Good God, sir,” exclaimed the officer, “is it possible?” And the next\nmoment his eye lighted up with professional ambition. “This will make a\ndeal of noise,” he said. “And perhaps you can help us to the man.” And\nhe briefly narrated what the maid had seen, and showed the broken stick.\nMr. Utterson had already quailed at the name of Hyde; but when the\nstick was laid before him, he could doubt no longer; broken and battered\nas it was, he recognised it for one that he had himself presented many\nyears before to Henry Jekyll.\n“Is this Mr. Hyde a person of small stature?” he inquired.\n“Particularly small and particularly wicked-looking, is what the maid\ncalls him,” said the officer.\nMr. Utterson reflected; and then, raising his head, “If you will come with\nme in my cab,” he said, “I think I can take you to his house.”",
